node --input-type=module <<'EOF'
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { mergePoWithTemplate, parsePo, serializePo, writeCatalog } from '@pantoken/i18n-engine';
import { NON_ROOT_LOCALES } from './docs/.vitepress/i18n.ts';
import { collectUnits, isCatalogedApiUnit, segmentMarkdown } from './docs/scripts/segment-markdown.ts';

const repoRoot = process.cwd();
const potPath = join(repoRoot, 'l10n/docs.api.pot');
const newUnits = collectUnits(segmentMarkdown(readFileSync('docs/api/index.md', 'utf8'))).filter(isCatalogedApiUnit);
const oldSource = execFileSync('git', ['show', 'HEAD:docs/guide/packages.md'], { encoding: 'utf8' });
const oldSourceUnits = collectUnits(segmentMarkdown(oldSource)).filter(isCatalogedApiUnit);
const positionsByKey = new Map();
oldSourceUnits.forEach((unit, index) => {
  const key = `${unit.kind}\0${unit.text}`;
  const positions = positionsByKey.get(key) ?? [];
  positions.push(index);
  positionsByKey.set(key, positions);
});

let totalFilled = 0;
for (const locale of NON_ROOT_LOCALES) {
  const poPath = join(repoRoot, 'l10n', locale, 'docs.api.po');
  if (!existsSync(poPath)) continue;
  await mergePoWithTemplate(poPath, potPath);
  const oldLocalized = execFileSync('git', ['show', `HEAD:docs/${locale}/guide/packages.md`], {
    encoding: 'utf8',
  }).replaceAll('/guide/packages', '/api/');
  const oldLocalizedUnits = collectUnits(segmentMarkdown(oldLocalized)).filter(isCatalogedApiUnit);
  const translatedByKey = new Map();
  for (const unit of newUnits) {
    const key = `${unit.kind}\0${unit.text}`;
    const indexes = positionsByKey.get(key) ?? [];
    const translations = indexes
      .map((index) => oldLocalizedUnits[index]?.text)
      .filter((text) => typeof text === 'string' && text.length > 0);
    if (translations.length > 0) translatedByKey.set(key, translations[0]);
  }

  let filled = 0;
  const entries = parsePo(readFileSync(poPath, 'utf8'));
  for (const entry of entries) {
    if (entry.obsolete || entry.msgctxt !== 'docs.api:prose' || entry.msgstr !== '') continue;
    const translation = translatedByKey.get(`prose\0${entry.msgid}`) ?? entry.msgid;
    entry.msgstr = translation;
    entry.fuzzy = false;
    entry.flags = entry.flags.filter((flag) => flag !== 'fuzzy');
    filled += 1;
  }
  if (filled > 0) writeCatalog(poPath, serializePo(entries));
  totalFilled += filled;
  console.log(`${locale}: filled ${filled} API overview prose entries`);
}
console.log(`filled ${totalFilled} API overview prose entries total`);
EOF","explanation":"Populate new docs.api PO entries for the API overview from the previously translated package guide pages.","goal":"Backfill API overview translations","mode":"sync","timeout":0}

